(function() {
  const STATE = {
    step: 1,
    totalSteps: 13,
    currentDilemma: null,
    amceData: null
  };

  // Load AMCE data from runtime tables
  function loadAmceData() {
    if (window.paperMindData && window.paperMindData.tables) {
      const table = window.paperMindData.tables.find(t => t.id === 'p6-fig2a');
      if (table) {
        // Extract row2 (Preference for action/right side) as baseline for visualization
        // Note: Values are strings, must parse carefully. Nulls handled.
        const row = table.rows.find(r => r.id === 'row2');
        if (row && row.values) {
          STATE.amceData = {
            species: parseFloat(row.values.Species) || 0,
            action: parseFloat(row.values.Intervention) || 0, // Sparing Pedestrians vs Passengers logic inverted in table structure, using raw delta
            role: parseFloat(row.values['Relation to AV']) || 0,
            number: parseFloat(row.values['No. Characters']) || 0,
            gender: parseFloat(row.values.Gender) || 0,
            age: parseFloat(row.values.Age) || 0,
            law: parseFloat(row.values.Law) || 0,
            fitness: parseFloat(row.values.Fitness) || 0,
            status: parseFloat(row.values['Social Status']) || 0
          };
        }
      }
    }
  }

  const DIMENSIONS = [
    { key: 'species', label: '物种', options: ['人类', '宠物'] },
    { key: 'action', label: '行动', options: ['保持原路线', '转向'] },
    { key: 'role', label: '角色位置', options: ['乘客', '行人'] },
    { key: 'number', label: '数量', options: ['较少生命', '更多生命'] },
    { key: 'gender', label: '性别', options: ['男性', '女性'] },
    { key: 'age', label: '年龄', options: ['老年人', '年轻人'] },
    { key: 'law', label: '守法', options: ['违规穿行', '合法穿行'] },
    { key: 'fitness', label: '体质', options: ['较弱者', '健康者'] },
    { key: 'status', label: '地位', options: ['低社会地位', '高社会地位'] }
  ];

  const CHARACTERS = [
    '成年男性', '成年女性', '男孩', '女孩', '老年男性', '老年女性',
    '孕妇', '医生', '运动员', '高管', '流浪汉', '罪犯', '大体型者',
    '狗', '猫'
  ];

  function generateDilemma() {
    // Simulate sampling from 26 million possibilities
    // Focusing on one primary dimension for the step
    const primaryDimIndex = (STATE.step - 1) % DIMENSIONS.length;
    const primaryDim = DIMENSIONS[primaryDimIndex];

    // Randomize other attributes
    const scenario = {
      id: STATE.step,
      primaryDim: primaryDim.key,
      primaryDimLabel: primaryDim.label,
      optionA: {},
      optionB: {}
    };

    // Generate characters for Option A (e.g., Stay on course)
    const countA = Math.floor(Math.random() * 3) + 1; // 1-3 chars
    const charsA = [];
    for(let i=0; i<countA; i++) {
      charsA.push(CHARACTERS[Math.floor(Math.random() * CHARACTERS.length)]);
    }

    // Generate characters for Option B (e.g., Swerve)
    const countB = Math.floor(Math.random() * 3) + 1;
    const charsB = [];
    for(let i=0; i<countB; i++) {
      charsB.push(CHARACTERS[Math.floor(Math.random() * CHARACTERS.length)]);
    }

    scenario.optionA = { label: '保持原路线', chars: charsA, count: countA };
    scenario.optionB = { label: '转向', chars: charsB, count: countB };

    return scenario;
  }

  function renderDilemma(scenario) {
    const sceneText = document.getElementById('scene-text');
    const charsAEl = document.getElementById('chars-a');
    const charsBEl = document.getElementById('chars-b');
    const feedback = document.getElementById('feedback-area');

    feedback.hidden = true;
    sceneText.textContent = `困境 #${scenario.id}: 自动驾驶汽车必须在以下两种结果中做出选择。主要变量聚焦于：${scenario.primaryDimLabel}。`;

    charsAEl.innerHTML = scenario.optionA.chars.map(c => `<div>• ${c}</div>`).join('');
    charsBEl.innerHTML = scenario.optionB.chars.map(c => `<div>• ${c}</div>`).join('');

    // Update variable grid to show current focus
    DIMENSIONS.forEach((dim, idx) => {
      const el = document.getElementById(`val-${dim.key}`);
      if (idx === (STATE.step - 1) % DIMENSIONS.length) {
        el.style.color = 'var(--warm)';
        el.style.fontWeight = 'bold';
      } else {
        el.style.color = 'var(--ink)';
        el.style.fontWeight = 'normal';
      }
    });
  }

  function renderAmceChart() {
    const container = document.getElementById('amce-chart');
    if (!STATE.amceData) return;

    container.innerHTML = '';
    const keys = Object.keys(STATE.amceData);

    keys.forEach(key => {
      const val = STATE.amceData[key];
      const dimObj = DIMENSIONS.find(d => d.key === key);
      const label = dimObj ? dimObj.label : key;

      const row = document.createElement('div');
      row.className = 'amce-bar-row';

      // Visual scaling: max expected ~0.5, so 100% width = 0.5
      const widthPct = Math.min(Math.abs(val) * 200, 100);
      const isNegative = val < 0;

      row.innerHTML = `
        <div class="amce-label">${label}</div>
        <div class="amce-track">
          <div class="amce-fill ${isNegative ? 'negative' : ''}" style="width: ${widthPct}%"></div>
        </div>
        <div class="amce-value">${val.toFixed(2)}</div>
      `;
      container.appendChild(row);
    });
  }

  function updateProgress() {
    document.getElementById('step-display').textContent = STATE.step;
    const pct = (STATE.step / STATE.totalSteps) * 100;
    document.getElementById('progress-fill').style.width = `${pct}%`;
  }

  function handleChoice(choice) {
    const feedback = document.getElementById('feedback-area');
    const choiceText = document.getElementById('user-choice-text');
    const highlight = document.getElementById('highlighted-dim');

    choiceText.textContent = STATE.currentDilemma[choice].label;
    highlight.textContent = STATE.currentDilemma.primaryDimLabel;
    feedback.hidden = false;

    // Advance step
    if (STATE.step < STATE.totalSteps) {
      STATE.step++;
      updateProgress();
      setTimeout(() => {
        STATE.currentDilemma = generateDilemma();
        renderDilemma(STATE.currentDilemma);
      }, 1000);
    } else {
      choiceText.textContent += ' (会话结束)';
    }
  }

  function init() {
    loadAmceData();
    renderAmceChart();
    updateProgress();

    STATE.currentDilemma = generateDilemma();
    renderDilemma(STATE.currentDilemma);

    document.getElementById('btn-generate').addEventListener('click', () => {
      STATE.currentDilemma = generateDilemma();
      renderDilemma(STATE.currentDilemma);
      document.getElementById('feedback-area').hidden = true;
    });

    document.getElementById('btn-reset').addEventListener('click', () => {
      STATE.step = 1;
      updateProgress();
      STATE.currentDilemma = generateDilemma();
      renderDilemma(STATE.currentDilemma);
      document.getElementById('feedback-area').hidden = true;
    });

    document.getElementById('choice-a').addEventListener('click', () => handleChoice('optionA'));
    document.getElementById('choice-b').addEventListener('click', () => handleChoice('optionB'));

    // Keyboard support
    document.getElementById('choice-a').addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        handleChoice('optionA');
      }
    });
    document.getElementById('choice-b').addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        handleChoice('optionB');
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
